// Carrara 3D — multiplayer server (free hosting friendly: one Node process serves the game and the WebSocket)
// Run:  npm install  &&  npm start      (PORT from the environment, default 3000)
const http = require('http'), fs = require('fs'), path = require('path'), { WebSocketServer } = require('ws');
const PORT = process.env.PORT || 3000, GAME = process.env.GAME_FILE || [path.join(__dirname, 'index.html'), path.join(__dirname, 'public', 'index.html')].find(f => fs.existsSync(f)) || null;
// the game itself is built in (gzip + base64), so server.js and package.json are all you need to upload
const GAME_EMBED = require('zlib').gunzipSync(Buffer.from(GAME_B64(), 'base64'));
const DATA = process.env.DATA_FILE || path.join(__dirname, 'data.json');
const TICK_MS = 125, RADIUS = 6000, NEAR = 500, MAX_VIS = 40, MAX_PLAYERS = +(process.env.MAX_PLAYERS || 150), MAX_MSG = 16000;

// ---- tiny document store for the leaderboard and cloud saves (kept in memory, flushed to data.json)
let DOCS = {}; try { DOCS = JSON.parse(fs.readFileSync(DATA, 'utf8')) } catch (e) {}
let dirty = false; setInterval(() => { if (!dirty) return; dirty = false; fs.writeFile(DATA, JSON.stringify(DOCS), () => {}) }, 10000);
const okPath = p => typeof p === 'string' && p.length < 200 && /^[A-Za-z0-9_\-/]+$/.test(p);

// ---- http: the game page and a health check
const server = http.createServer((req, res) => {
  if (req.url === '/health') { res.writeHead(200, { 'content-type': 'text/plain' }); return res.end('ok ' + clients.size) }
  const done = (err, buf) => {
    if (err) { buf = GAME_EMBED }
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-cache' }); res.end(buf)
  };
  if (GAME) fs.readFile(GAME, done); else done(null, GAME_EMBED)
});

// ---- realtime: rooms with presence, sent only to players nearby
const wss = new WebSocketServer({ server, path: '/ws', maxPayload: MAX_MSG });
const clients = new Map(); let nextPeer = 1;
const rooms = new Map(); // room -> Map(peer -> {pres, ver, by})
function roomOf(n) { if (!rooms.has(n)) rooms.set(n, new Map()); return rooms.get(n) }
function send(c, o) { if (c.ws.readyState === 1) c.ws.send(JSON.stringify(o)) }
function near(a, b) {
  const p = a && a.p, q = b && b.p; if (!Array.isArray(p) || !Array.isArray(q)) return true;
  return Math.abs(p[0] - q[0]) < RADIUS && Math.abs(p[2] - q[2]) < RADIUS
}
wss.on('connection', (ws) => {
  if (clients.size >= MAX_PLAYERS) { ws.close(1013, 'full'); return }
  const c = { ws, peer: 'p' + (nextPeer++), by: null, rooms: new Set(), seen: new Map(), alive: true };
  clients.set(c.peer, c);
  ws.on('pong', () => c.alive = true);
  ws.on('message', (raw) => {
    let m; try { m = JSON.parse(raw) } catch (e) { return }
    if (m.t === 'hello') { c.by = String(m.id || '').slice(0, 60) || c.peer; send(c, { t: 'hello', peer: c.peer, id: c.by }); return }
    if (m.t === 'join' && typeof m.room === 'string' && m.room.length < 40) { c.rooms.add(m.room); roomOf(m.room).set(c.peer, { pres: {}, ver: 0, by: c.by }); c.seen.set(m.room, new Map()); send(c, { t: 'joined', room: m.room }); return }
    if (m.t === 'leave') { leave(c, m.room); return }
    if (m.t === 'p' && c.rooms.has(m.room) && m.st && typeof m.st === 'object') {
      const e = roomOf(m.room).get(c.peer); if (!e) return;
      for (const k in m.st) { if (k === 'dbg') continue; if (m.st[k] === null) delete e.pres[k]; else e.pres[k] = m.st[k] }
      e.ver++; return
    }
    if (m.t === 'get' && okPath(m.path)) { send(c, { t: 'doc', rid: m.rid, data: DOCS[m.path] || null }); return }
    if (m.t === 'set' && okPath(m.path) && m.data && typeof m.data === 'object') {
      // a player may only write their own documents
      if (!(m.path === 'lb/' + c.by || m.path.startsWith('data/users/' + c.by + '/'))) { send(c, { t: 'doc', rid: m.rid, err: 'denied' }); return }
      DOCS[m.path] = m.data; dirty = true; lbDirty = lbDirty || m.path.startsWith('lb/'); send(c, { t: 'doc', rid: m.rid, ok: 1 }); return
    }
    if (m.t === 'lbsub') { c.lb = true; sendLb(c); return }
  });
  ws.on('close', () => { for (const r of [...c.rooms]) leave(c, r); clients.delete(c.peer) });
});
function leave(c, room) { if (!c.rooms.has(room)) return; c.rooms.delete(room); const R = rooms.get(room); if (R) { R.delete(c.peer); if (!R.size) rooms.delete(room) } c.seen.delete(room) }
// every tick: tell each player what changed among the players near them
let tick = 0;
function dist(a, b) { const p = a && a.p, q = b && b.p; if (!Array.isArray(p) || !Array.isArray(q)) return 0; return Math.hypot(p[0] - q[0], p[2] - q[2]) }
setInterval(() => {
  tick++;
  for (const c of clients.values()) for (const room of c.rooms) {
    const R = rooms.get(room); if (!R) continue; const me = R.get(c.peer), seen = c.seen.get(room) || new Map();
    const peers = [], joined = [], left = [], vis = new Set();
    // the nearest players get every update; farther ones once a second; at most MAX_VIS are shown
    const cand = [];
    for (const [peer, e] of R) { if (peer === c.peer) continue; if (!near(me && me.pres, e.pres)) continue; cand.push([dist(me && me.pres, e.pres), peer, e]) }
    cand.sort((a, b) => a[0] - b[0]);
    for (const [d, peer, e] of cand.slice(0, MAX_VIS)) {
      vis.add(peer);
      if (!seen.has(peer)) joined.push({ peer, by: e.by, kind: 'viewer' });
      if (seen.get(peer) !== e.ver && (d < NEAR || !seen.has(peer) || tick % 8 === 0)) { peers.push({ peer, by: e.by, kind: 'viewer', presence: e.pres }); seen.set(peer, e.ver) }
    }
    for (const peer of [...seen.keys()]) if (!vis.has(peer)) { left.push({ peer }); seen.delete(peer) }
    c.seen.set(room, seen);
    if (peers.length || left.length || joined.length) send(c, { t: 'peers', room, peers, joined, left })
  }
}, TICK_MS);
// leaderboard: top 100 by money, pushed to subscribers when it changes
let lbDirty = true;
function lbRows() { return Object.entries(DOCS).filter(([k]) => k.startsWith('lb/')).map(([k, v]) => ({ id: k.slice(3), ...v })).sort((a, b) => (b.m || 0) - (a.m || 0)).slice(0, 100) }
function sendLb(c) { send(c, { t: 'lb', rows: lbRows() }) }
setInterval(() => { if (!lbDirty) return; lbDirty = false; for (const c of clients.values()) if (c.lb) sendLb(c) }, 5000);
// drop dead connections
setInterval(() => { for (const c of clients.values()) { if (!c.alive) { c.ws.terminate(); continue } c.alive = false; try { c.ws.ping() } catch (e) {} } }, 30000);
server.listen(PORT, () => console.log('Carrara 3D server on :' + PORT + ' (max ' + MAX_PLAYERS + ' players)'));

function GAME_B64(){return ''}
